WITH base AS (SELECT *, COALESCE(location, 'N/A') AS location_filled, COALESCE(dept_name, 'OTHER') AS resolved_dept_name FROM departments WHERE location IS NOT NULL), valid AS (SELECT *, ROUND(budget * 1.15, 2) AS adjusted_budget, ROUND(budget, 2) AS budget_rounded FROM base WHERE location IS NOT NULL), ranked AS (SELECT id, dept_name, location, location_filled, resolved_dept_name FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY location, dept_name ORDER BY budget NULLS FIRST, id) AS rank_in_group FROM valid) x WHERE rank_in_group = 1), eligible AS (SELECT s.* FROM ranked s WHERE NOT EXISTS (SELECT 1 FROM employees c WHERE c.dept_id = s.id AND c.level NOT IN ('L1', 'L3', 'L5'))) SELECT id, dept_name, location, location_filled, resolved_dept_name, CASE WHEN dept_name RLIKE '^(Legal|Finance)$' THEN 'EXTENDED' ELSE 'CORE' END AS dept_name_zone FROM eligible ORDER BY location DESC NULLS LAST;
